<template>
  <Card>
    <CardHeader>
      <CardTitle>Targets</CardTitle>
    </CardHeader>
    <CardContent class="grid grid-cols-1 sm:grid-cols-2 gap-4">
      <LabeledValue v-for="(item, index) in info" :key="index" :label="item.label" :value="item.value" />
      <LabeledValue v-if="pausedByUser" label="Paused By">
        <InlineEntityUser :user="pausedByUser" />
      </LabeledValue>
    </CardContent>
  </Card>
</template>

<script setup lang="ts">
import type { GetCampaignDetailsResponse } from '~/client';
import { getCampaignPauseReason } from '~/constants/recruitment/campaignPauseReasonConfig';

const props = defineProps<{
  data: GetCampaignDetailsResponse;
}>();

const { timezone } = useUserRole();

const info = computed(() => [
  {
    label: 'Application Target',
    value: `${props.data.applications_count} / ${props.data.target_application_count ?? '—'}`,
  },
  {
    label: 'Assignment Target',
    value: `${props.data.assignments_count} / ${props.data.target_assignment_count ?? '—'}`,
  },
  {
    label: 'Paused At',
    value: props.data.paused_at
      ? formatDateTzToFormat(props.data.paused_at, 'MM/dd/yyyy, hh:mm aaa', timezone.value)
      : '—',
  },
  {
    label: 'Pause Reason',
    value: props.data.paused_reason ? getCampaignPauseReason(props.data.paused_reason).label : '—',
  },
]);

const pausedByUser = computed(() =>
  props.data.paused_reason === 'manual' ? (props.data.paused_by_user ?? undefined) : undefined
);
</script>
